CREATE TABLE "operation_inputs" ("operation_id" TEXT NOT NULL REFERENCES operations (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "display_name" TEXT NOT NULL, "mime" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL, "meta_json" TEXT NULL, PRIMARY KEY ("operation_id", "position"));
CREATE TABLE "operations" ("id" TEXT NOT NULL, "tool" TEXT NOT NULL, "status" TEXT NOT NULL, "error_code" TEXT NULL, "created_at" INTEGER NOT NULL, "finished_at" INTEGER NULL, "duration_ms" INTEGER NULL, "input_count" INTEGER NOT NULL, "input_total_bytes" INTEGER NOT NULL, "output_name" TEXT NULL, "output_mime" TEXT NULL, "output_bytes" INTEGER NULL, "output_rel_path" TEXT NULL, "output_meta_json" TEXT NULL, "options_json" TEXT NULL, "saved_externally" INTEGER NOT NULL DEFAULT 0 CHECK ("saved_externally" IN (0, 1)), "output_deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_ops_created ON operations (created_at DESC);
CREATE INDEX idx_ops_tool ON operations (tool);
